    case 0x01: return ReqUserLogin(pDBStmt, xPacket, xReturnSessionID);
    case 0x02: return ReqUserLogout(pDBStmt, xPacket, xReturnSessionID);
    case 0x03: return ReqUserLoginForNHN(pDBStmt, xPacket, xReturnSessionID);
