    // Per IDA 0x14001CAA0: SP_CHARACTER_SLOT_CHANGE (MainCmd=3, SubCmd=0x06)
    PS_CHARACTER_CHANGE_SLOT stSlot;
    xPacket >> stSlot;

    std::int16_t sqlReturn = -1;

    XDBBinder xDBBinder(pDBStmt);
