    PS_REQ_LEAGUE_DELEGATE psDelegateReq;
    xPacket >> psDelegateReq;

    std::uint32_t dwMasterUCID = 0;
    std::uint32_t dwServerID = 0;
    xPacket.XParse >> dwMasterUCID;
    xPacket.XParse >> dwServerID;

