    xDBBinder.SetData(&stForceReq.stMember.nChannel, 4);
    xDBBinder.SetData(&stForceReq.nErrorCode, 4);

    sqlReturn = xDBBinder.Execute(reinterpret_cast<unsigned char*>(const_cast<char*>("{call SP_FORCE_JOIN(?, ?, ?, ?)}")));

