        if (sqlReturn == 100) {
            sqlReturn = 0;
        }
        LogHelper::LogError("game.contents", "[ SP_201808COSTUME_EVENT_LOAD ] [UAID:%d] [%d error]", stPlayTime.dwUAID, sqlReturn);
